@Composable
fun RabbitLoadingIndicator(modifier: Modifier = Modifier) {
    val useAppIconStyleLoadingIndicator = LocalSettings.current.displaySetting.useAppIconStyleLoadingIndicator

    if (useAppIconStyleLoadingIndicator) {
        val transition = rememberInfiniteTransition(label = "claudeSpark")
        val frameProgress by transition.animateFloat(
            initialValue = 0f,
            targetValue = ClaudeSparkFrames.size.toFloat(),
            animationSpec = infiniteRepeatable(
                animation = tween(
                    durationMillis = ClaudeSparkFrames.size * ClaudeSparkFrameDurationMillis,
                    easing = LinearEasing,
                ),
                repeatMode = RepeatMode.Restart,
            ),
            label = "claudeSparkFrame",
        )
        val frameIndex = floor(frameProgress).toInt().coerceIn(0, ClaudeSparkFrames.lastIndex)

        val sparkColor = MaterialTheme.colorScheme.primary
        Canvas(modifier = modifier) {
            drawClaudeSparkFrame(
                frameIndex = frameIndex,
                color = sparkColor,
            )
        }
    } else {
        ContainedLoadingIndicator(
            modifier = modifier,
        )
    }
}

private fun DrawScope.drawClaudeSparkFrame(frameIndex: Int, color: Color) {
    val path = ClaudeSparkFrames[frameIndex]
    val scaleFactor = minOf(
        size.width / ClaudeSparkViewport,
        size.height / ClaudeSparkViewport,
    )
    val scaledSize = Size(ClaudeSparkViewport * scaleFactor, ClaudeSparkViewport * scaleFactor)
    val offsetX = (size.width - scaledSize.width) / 2f
    val offsetY = (size.height - scaledSize.height) / 2f

    withTransform({
        translate(left = offsetX, top = offsetY)
        scale(scaleX = scaleFactor, scaleY = scaleFactor, pivot = Offset.Zero)
    }) {
        drawPath(
            path = path,
            color = color,
        )
    }
}
